  function checkReminders(){if(!currentUser||!reminderMinutes)return;let now=Date.now(),future=addDays(today,2);for(const e of eventInstances(today,future)){let at=getStart(e.instanceDate,e).getTime()-reminderMinutes*60000,key=`${currentUser.id}|${e.id}|${iso(e.instanceDate)}`;if(now>=at&&now<at+60000&&!reminderShown.has(key)){reminderShown.add(key);let message=`${e.title} starts in ${reminderMinutes} minutes${e.room?` · ${e.room}`:''}`;if('Notification'in window&&Notification.permission==='granted')new Notification('Upcoming class',{body:message,icon:'./icon.svg'});notify(message)}}}
